import { cn } from "@/lib/utils";
import type { ImgHTMLAttributes } from "react";

/**
 * The MeterPal wordmark in the checkout footer.
 *   /meterpal-logo-color.svg <- assets/images/logo.svg       (light surfaces)
 *   /meterpal-logo-white.svg <- assets/images/logo-white.svg (dark surfaces)
 * Both files are generated by scripts/sync-brand-assets.mjs.
 *
 * Kept under the upstream filename/export so existing imports keep working,
 * but there are no baked-in SVG paths here anymore.
 */
export function MeterPalLogo({
	className,
	alt = "MeterPal",
	...props
}: ImgHTMLAttributes<HTMLImageElement>) {
	return (
		<>
			<img
				src="/meterpal-logo-color.svg"
				alt={alt}
				className={cn(className, "dark:hidden")}
				{...props}
			/>
			<img
				src="/meterpal-logo-white.svg"
				alt={alt}
				className={cn(className, "hidden dark:block")}
				{...props}
			/>
		</>
	);
}

/** Backwards-compatible alias for the upstream Autumn component name. */
export const AutumnLogo = MeterPalLogo;
